"""Canonical factorization with a prescribed pole profile.

Given a target g of valuation val(g), a slot count m >= 1, a renormalizing exponent k
and a pole profile d with val(g) = k + sum(d[:m]), the algorithm returns a family
f_0, ..., f_{m-1} with val(f_i) = d_i and q^k * prod f_i = g.  Slots 1..m-1 carry pure
monomials q^{d_i} and slot 0 absorbs everything else.  Cost: O(m) monomial assignments
plus one shift of g; correctness is the realizability theorem.
"""

from __future__ import annotations

from fractions import Fraction
from typing import List, Sequence, Tuple

# A truncated Laurent series is a pair (valuation, coefficient list), the list
# starting at the valuation and having a nonzero first entry.
Series = Tuple[int, List[Fraction]]

PREC: int = 16


def normalize(val: int, coeffs: Sequence[Fraction]) -> Series:
    c = [Fraction(x) for x in coeffs]
    s = 0
    while s < len(c) and c[s] == 0:
        s += 1
    if s == len(c):
        return (0, [])
    return (val + s, c[s : s + PREC])


def valuation(f: Series) -> float:
    return float("inf") if not f[1] else float(f[0])


def shift(f: Series, e: int) -> Series:
    """Multiply by the monomial q^e."""
    return normalize(f[0] + e, f[1])


def canonical_factorization(g: Series, m: int, k: int, d: Sequence[int]) -> List[Series]:
    if m < 1:
        raise ValueError("need at least one slot")
    total = k + sum(d[:m])
    if valuation(g) != float(total):
        raise ValueError(f"target has valuation {valuation(g)}, profile forces {total}")
    tail = sum(d[1:m])
    f0 = shift(g, -k - tail)
    return [f0] + [normalize(d[i], [Fraction(1)]) for i in range(1, m)]
